/// Parse `src` as `nest_sum` and deserialize `T` from the result.
///
/// `filename` names the source in the parser's diagnostics. Trivia is not captured:
/// unlabeled children are skipped, so there is nothing to capture it for.
pub fn from_str<T: ::serde::de::DeserializeOwned>(src: &str, filename: Option<&str>) -> Result<T, ::fltk_serde_core::ParseToTargetError> {
    let mut parser = parser::Parser::new(src, filename, false);
    let result = parser.apply__parse_nest_sum(0);
    // A depth-rejected parse can still come back as `Some` holding a wrong tree.
    if parser.depth_exceeded() {
        return Err(::fltk_serde_core::ParseToTargetError::Parse(parser.error_message()));
    }
    let Some(parsed) = result else {
        return Err(::fltk_serde_core::ParseToTargetError::Parse(parser.error_message()));
    };
    // The whole input has to be consumed; `pos` counts characters, not bytes.
    if parsed.pos != src.chars().count() as i64 {
        return Err(::fltk_serde_core::ParseToTargetError::Parse(parser.error_message()));
    }
    Ok(from_nest_sum_cst(&parsed.result)?)
}
